// src/components/pages/Home.js
import React from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import PageWrapper from "../PageWrapper";

const Home = () => {
  const navigate = useNavigate();

  return (
    <PageWrapper>
      <div className="flex justify-center items-start min-h-screen bg-gray-100 px-6 pt-20">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="bg-white rounded-3xl shadow-2xl p-10 max-w-3xl w-full text-center"
        >
          <h1 className="text-4xl font-bold text-black mb-6">Welcome Back!</h1>
          <p className="text-black text-lg mb-10">
            Choose one of the options below to start your AI interview journey.
          </p>

          <div className="flex flex-col md:flex-row justify-center gap-6">
            <button
              onClick={() => navigate("/interview")}
              className="bg-black hover:bg-gray-900 text-white font-semibold px-8 py-4 rounded-full shadow-lg transition-all duration-300"
            >
              Start Interview
            </button>

            <button
              onClick={() => navigate("/practice")}
              className="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold px-8 py-4 rounded-full shadow-lg transition-all duration-300"
            >
              Practice Questions
            </button>
          </div>
        </motion.div>
      </div>
    </PageWrapper>
  );
};

export default Home;
